+567: /** Preserve raw stopped product/history bytes; exclude executables and unrelated Electron caches. */
+568: async function preserveDonorCorpus(root: string, teamName: string) {
+569:   const directory = join(root, 'evidence-corpus');
+570:   const files: { path: string; copy: string; bytes: number; sha256: string }[] = [];
+571:   let totalBytes = 0;
+572:   const visit = async (relative: string): Promise<void> => {
+573:     if (relative === 'claude/local' || /\/host-authority\/[a-f0-9]{64}\/images$/.test(relative)) return;
+574:     // The stock profile links dependencies to its shared cache and owns a separate temp directory.
+575:     if (/^runtime-data\/opencode\/profiles\/[^/]+\/(?:config\/opencode\/node_modules|tmp)$/.test(relative)) return;
+576:     const path = join(root, relative), before = await lstat(path, { bigint: true });
+577:     assert.equal(before.isSymbolicLink(), false, 'raw corpus never follows a link');
+578:     if (before.isDirectory()) {
+579:       for (const entry of (await readdir(path)).sort()) await visit(relative + '/' + entry);
+580:       return;
+581:     }
+582:     assert.ok(before.isFile() && before.nlink === 1n && before.uid === BigInt(process.getuid!()));
+583:     assert.ok(files.length < 4096 && before.size <= 64n * 1024n * 1024n, 'finite raw corpus file budget');
+584:     const bytes = await readFile(path), after = await lstat(path, { bigint: true });
+585:     assert.ok(before.dev === after.dev && before.ino === after.ino && before.size === after.size &&
+586:       before.mtimeNs === after.mtimeNs && before.ctimeNs === after.ctimeNs, 'stopped corpus stays current during capture');
+587:     totalBytes += bytes.length; assert.ok(totalBytes <= 256 * 1024 * 1024, 'finite raw corpus byte budget');
+588:     const copy = `file-${String(files.length).padStart(5, '0')}.bin`;
+589:     await writeFile(join(directory, copy), bytes, { mode: 0o600, flag: 'wx' });
