+88: /** Passive projection of the existing TEST peer journal, after original cleanup attempts. */
+89: export function observeEmulatedSourcePeerReadiness(
+90:   evidence: Record<string, unknown>, values: readonly Record<string, unknown>[], provider: string
+91: ): void {
+92:   if (provider !== 'codex') return;
+93:   try {
+94:     const data = (row: object, key: string): unknown => {
+95:       const property = Object.getOwnPropertyDescriptor(row, key);
+96:       if (property && !('value' in property)) throw new Error('TEST non-data peer observation');
+97:       return property?.value;
+98:     };
+99:     const integer = (value: unknown, maximum = Number.MAX_SAFE_INTEGER): value is number =>
+100:       typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= maximum;
+101:     const events: Record<string, unknown>[] = [];
+102:     let truncated = false;
+103:     for (const [index, value] of values.entries()) {
+104:       if (data(value, 'provider') !== 'codex') continue;
+105:       const event = data(value, 'event');
+106:       if (typeof event !== 'string' ||
+107:           !['launch', 'mcp-catalog', 'managed-configuration-read', 'connected', 'exit'].includes(event)) continue;
+108:       if (events.length === 64) { truncated = true; break; }
+109:       const pid = data(value, 'pid'), role = data(value, 'role');
+110:       assert.ok(integer(pid) && pid > 0 && (role === 'runtime' || role === 'management'));
+111:       const row: Record<string, unknown> = { ordinal: index + 1, event, pid, role };
+112:       if (event === 'launch') {
+113:         const parentPid = data(value, 'parentPid'), argc = data(value, 'argc');
+114:         assert.ok(integer(parentPid) && parentPid > 0 && integer(argc, 1024));
+115:         row.parentPid = parentPid; row.argc = argc;
+116:       } else if (event === 'mcp-catalog') {
+117:         const configuredServers = data(value, 'configuredServers');
+118:         assert.ok(integer(configuredServers, 256)); row.configuredServers = configuredServers;
+119:       } else if (event === 'managed-configuration-read') {
+120:         const selected = data(value, 'selectedServers');
+121:         assert.ok(Array.isArray(selected) && selected.length <= 1 && selected.every(name => name === 'team'));
+122:         row.selectedServerCount = selected.length; row.teamSelected = selected.includes('team');
+123:       } else if (event === 'connected') {
+124:         const tools = data(value, 'tools');
+125:         assert.ok(Array.isArray(tools) && tools.length <= 256 && tools.every(name => typeof name === 'string'));
+126:         row.toolCount = tools.length;
+127:       } else {
+128:         const code = data(value, 'code');
+129:         assert.ok(code === 0 || code === 1); row.code = code;
+130:       }
+131:       events.push(row);
+132:     }
+133:     evidence.sourcePeerReadiness = {
+134:       status: 'observed', provider, capturePoint: 'existing-post-cleanup-effects-read',
+135:       atomicWithReadinessFailure: false, events, truncated,
+136:     };
+137:   } catch {
+138:     try { evidence.sourcePeerReadiness = { status: 'unknown', provider }; }
+139:     catch { /* Passive evidence cannot replace the original failure or pin check. */ }
+140:   }
+141: }
